Ext.define('BNK.view.Budget.exp.ExpNteRcpt01MContainerViewController', {
    extend: 'BaseViewController',
    alias: 'controller.ExpNteRcpt01MContainerViewController',

    config: {
        viewId: 'ExpNteRcpt01MContainer'
    },

    /* Card화면전환 */
    showView: function(itemId) {
        var me = this;
        me.getView().setActiveItem(itemId);
    },

    /* + 버튼 탭으로 지출결의서 Form 추가 */
    onAddForm: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            items = refs.items,
            item = null;

        // 영수증 작성 미완료 시 추가 form 생성 방지
        var innerItems = refs.items.innerItems;
        for(var i in innerItems){
            var formData = innerItems[i].getViewModel().get('etcItem');

            formData.btnPlus = true;

            var errMsg = this.getView().up().up().controller.formValid(formData);
            if(formData.useYn && errMsg.length > 0){
                //Ext.Msg.alert('유효성 검사', '모두 입력해 주세요.');
                return false;
            }
        }

        item = Ext.create('ExpNteRcpt01MItems', { // alternateClassName : ITEMs // userClassName과 다름
            atomItemIdx : refs.items.innerItems.length
        });
        items.add(item);

    },

    /* 화면초기화 */
    initialize: function(component, eOpts) {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();

        vm.set('today', DateUtils.encodeDate(new Date(), 'Y-m-d'));

        me.onAddForm();

    }

});